begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.vi(t text) returns uuid language sql immutable as $$select md5('visitor-qr-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.vi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.vi(x),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',x||'-vq@example.invalid',now(),now(),now() from unnest(array['owner','member']) x;
insert into public.organizations(id,name,slug,status) values(pg_temp.vi('org'),'Igreja fictícia QR','visitor-qr-test','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.vi('unit'),pg_temp.vi('org'),'Sede fictícia QR','sede','headquarters');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) select pg_temp.vi('org'),pg_temp.vi(x),case when x='owner' then 'owner' else 'member' end::public.membership_role,'active',pg_temp.vi('unit') from unnest(array['owner','member']) x;
select ok(has_function_privilege('anon','public.visitor_checkin(uuid,jsonb)','execute'),'visitante sem conta usa o QR');
select ok(not has_table_privilege('anon','private.visitor_entries','select'),'visitas sem leitura direta');
set local role anon;
select is(public.visitor_page(pg_temp.vi('unit'))->>'church','Sede fictícia QR','página mostra a igreja');
select is(public.visitor_page(pg_temp.vi('nada'))->>'found','false','igreja inexistente');
select throws_ok($$select public.visitor_checkin(pg_temp.vi('unit'),'{"name":"Ana","phone":"11988887777","consent":true}')$$,'22023','visitor_name','pede nome e sobrenome');
select throws_ok($$select public.visitor_checkin(pg_temp.vi('unit'),'{"name":"Ana Souza","phone":"123","consent":true}')$$,'22023','visitor_phone','pede WhatsApp válido');
select throws_ok($$select public.visitor_checkin(pg_temp.vi('unit'),'{"name":"Ana Souza","phone":"11988887777"}')$$,'22023','visitor_consent','pede o consentimento');
select is(public.visitor_checkin(pg_temp.vi('unit'),'{"name":"Ana Souza","phone":"(11) 98888-7777","consent":true,"firstTime":true,"heard":"friend","contact":true,"prayer":"Pela família"}')->>'firstName','Ana','cadastro pelo QR');
select ok(public.visitor_checkin(pg_temp.vi('unit'),'{"name":"Ana Souza","phone":"11988887777","consent":true}') ? 'person' = false,'resposta pública não expõe o cadastro');
reset role;
select is((select count(*)::int from public.people where organization_id=pg_temp.vi('org') and journey_status='Visitante' and followup_status='pending'),1,'vira visitante com acompanhamento pendente');
select is((select count(*)::int from private.visitor_entries where unit_id=pg_temp.vi('unit')),1,'mesmo dia não duplica visita');
select is((select answers->>'prayer' from private.visitor_entries limit 1),'Pela família','respostas guardadas');
set local role authenticated;
select pg_temp.actor('member');
select throws_ok($$select public.visitor_staff(pg_temp.vi('org'),pg_temp.vi('unit'),'save','{"name":"Bia Lima","phone":"11977776666"}')$$,'42501','visitor_denied','membro comum não cadastra pela equipe');
select pg_temp.actor('owner');
select ok(public.visitor_staff(pg_temp.vi('org'),pg_temp.vi('unit'),'save','{"name":"Bia Lima","phone":"11977776666","note":"Veio com a Ana"}')->>'person' is not null,'equipe cadastra sem consentimento digital');
select is(jsonb_array_length(public.visitor_staff(pg_temp.vi('org'),pg_temp.vi('unit'),'recent')->'items'),2,'equipe vê os visitantes recentes');
select is(jsonb_array_length(public.person_visits(pg_temp.vi('org'),(select id from public.people where full_name='Ana Souza'))->'items'),1,'ficha mostra a visita');
select pg_temp.actor('member');
select is(jsonb_array_length(public.person_visits(pg_temp.vi('org'),(select id from public.people where full_name='Ana Souza'))->'items'),0,'membro comum não vê visitas');
select pg_temp.actor('owner');
select is((select (x->>'visitors')::boolean from jsonb_array_elements(public.staff_access(pg_temp.vi('org'),'mine','{}')->'units') x limit 1),true,'Vinha Equipe sabe quem cadastra visitante');
select * from finish();
rollback;
